import type { ExerciseItem, HomeworkQuestionAnswer } from '@/types'

export interface QuestionStrategy {
  /**
   * 获取题型的默认作答值
   */
  getDefaultAnswer(): any

  /**
   * 校验作答内容是否为空
   * @param val 作答内容 (userAnswer)
   */
  isEmpty(val: any): boolean

  /**
   * 校验用户作答是否正确
   * @param val 用户作答值
   * @param standardAnswer 标准答案
   */
  checkCorrect(val: any, standardAnswer: any): boolean

  /**
   * 格式化作答数据，用于提交作业接口
   * @param val 用户作答值
   * @param questionIndex 题目在列表中的索引值
   * @param buildSubAnswer 辅助递归函数，供复合题使用
   * @param question 原始题目对象，用于获取题目结构元信息（如填空题空数）
   */
  formatForSubmit(val: any, questionIndex: number, buildSubAnswer?: (subQ: any, subIndex: number, parentVal?: any) => any, question?: any): any

  /**
   * 构建错题本所需要的特定作答结构对象
   * @param val 用户作答值
   */
  buildOriginalAnswer(val: any): any
}

// 1. 选择题策略 (单选 / 多选)
class ChoiceStrategy implements QuestionStrategy {
  getDefaultAnswer() {
    return []
  }

  isEmpty(val: any): boolean {
    return !Array.isArray(val) || val.length === 0
  }

  checkCorrect(val: any, standardAnswer: any): boolean {
    if (!val || !Array.isArray(val) || val.length === 0) return false
    const standardChoices = Array.isArray(standardAnswer)
      ? standardAnswer
      : [String(standardAnswer)]
    if (val.length !== standardChoices.length) return false
    return val.every((c) => standardChoices.includes(c))
  }

  formatForSubmit(val: any, questionIndex: number, buildSubAnswer?: any, question?: any) {
    return Array.isArray(val) ? val.map(String) : []
  }

  buildOriginalAnswer(val: any) {
    return { chooseList: val || [] }
  }
}

// 2. 判断题策略
class JudgmentStrategy implements QuestionStrategy {
  getDefaultAnswer() {
    return []
  }

  isEmpty(val: any): boolean {
    return !Array.isArray(val) || val.length === 0
  }

  checkCorrect(val: any, standardAnswer: any): boolean {
    if (!val || !Array.isArray(val) || val.length === 0) return false
    return String(standardAnswer) === String(val[0])
  }

  formatForSubmit(val: any, questionIndex: number, buildSubAnswer?: any, question?: any) {
    return Array.isArray(val) ? val.map(String) : []
  }

  buildOriginalAnswer(val: any) {
    const rawVal = Array.isArray(val) && val.length > 0 ? val[0] : ''
    return { judgmentValue: rawVal }
  }
}

// 3. 填空题策略
class FillBlankStrategy implements QuestionStrategy {
  getDefaultAnswer() {
    return []
  }

  isEmpty(val: any): boolean {
    if (!Array.isArray(val) || val.length === 0) return true
    // 判断是否有任何一空已经作答
    return !val.some((item) => {
      if (!item) return false
      if (typeof item === 'object') {
        if (item.type === 'photo') {
          return !!item.photoUrl
        }
        const boardData = item.boardData || item
        const hasObjects = Array.isArray(boardData?.objects) && boardData.objects.length > 0
        const hasPhoto = !!item.photoUrl
        return hasObjects || hasPhoto
      }
      return !!item.trim()
    })
  }

  checkCorrect(): boolean {
    return false // 填空题非客观自动判定
  }

  formatForSubmit(val: any, questionIndex: number, buildSubAnswer?: any, question?: any) {
    if (this.isEmpty(val)) {
      return []
    }
    const blanks = question?.structuredContent?.blanks
    const blankCount = Array.isArray(blanks) ? blanks.length : (typeof blanks === 'number' ? blanks : 0)
    const resultList = Array.from({ length: blankCount }, () => '')

    if (Array.isArray(val)) {
      val.forEach((item: any, idx: number) => {
        if (idx >= blankCount) return
        if (typeof item === 'object' && item !== null) {
          const isPhoto = item.type === 'photo'
          const boardData = item.boardData || item
          const hasObjects = Array.isArray(boardData?.objects) && boardData.objects.length > 0
          const hasPhoto = !!item.photoUrl
          
          if (isPhoto && hasPhoto) {
            resultList[idx] = item.photoUrl || ''
          } else if (!isPhoto && (hasObjects || hasPhoto)) {
            resultList[idx] = item.boardImg || ''
          } else {
            // 没有笔迹或图片，属于未作答，填充空字符串
            resultList[idx] = ''
          }
        } else if (typeof item === 'string') {
          resultList[idx] = item.trim()
        }
      })
    }
    return resultList
  }

  buildOriginalAnswer(val: any) {
    return { fillList: val || [] }
  }
}

// 4. 主观题策略
class SubjectiveStrategy implements QuestionStrategy {
  getDefaultAnswer() {
    return {
      type: 'board',
      boardData: { objects: [], history: [[]], historyIndex: 0 },
      boardImg: '',
      photoUrl: ''
    }
  }

  isEmpty(val: any): boolean {
    if (!val) return true
    if (typeof val === 'object') {
      if (val.type === 'photo') {
        return !val.photoUrl
      }
      const boardData = val.boardData || val
      // 如果没有绘制任何对象，并且也没有 photoUrl，则视为空
      const hasObjects = Array.isArray(boardData?.objects) && boardData.objects.length > 0
      const hasPhoto = !!val.photoUrl
      return !hasObjects && !hasPhoto
    }
    return !val.trim()
  }

  checkCorrect(): boolean {
    return false // 主观题非自动判定
  }

  formatForSubmit(val: any, questionIndex: number, buildSubAnswer?: any, question?: any) {
    if (this.isEmpty(val)) {
      return ''
    }
    if (typeof val === 'object' && val !== null) {
      if (val.type === 'photo') {
        return val.photoUrl || ''
      }
      return val.boardImg || ''
    }
    return ''
  }

  buildOriginalAnswer(val: any) {
    return {
      subjectiveData: val || {
        type: 'board',
        boardData: { objects: [], history: [[]], historyIndex: 0 },
        boardImg: '',
        photoUrl: ''
      }
    }
  }
}

// 5. 复合题策略
class CompositeStrategy implements QuestionStrategy {
  getDefaultAnswer() {
    return {}
  }

  isEmpty(val: any): boolean {
    return !val || typeof val !== 'object' || Object.keys(val).length === 0
  }

  checkCorrect(): boolean {
    return false // 复合题非整题客观自动判定
  }

  formatForSubmit(val: any, questionIndex: number, buildSubAnswer?: (subQ: any, subIndex: number, parentVal?: any) => any, question?: any) {
    const nestedAnswers: any[] = []
    if (buildSubAnswer) {
      // 实际逻辑在 buildAnswerForQuestion 中通过回调实现
    }
    return nestedAnswers
  }

  buildOriginalAnswer(val: any) {
    return { compositeAnswers: val || {} }
  }
}

// 策略导出字典
const strategies: Record<string, QuestionStrategy> = {
  single_choice: new ChoiceStrategy(),
  multiple_choice: new ChoiceStrategy(),
  true_false: new JudgmentStrategy(),
  judgment: new JudgmentStrategy(),
  fill_in_blank: new FillBlankStrategy(),
  subjective: new SubjectiveStrategy(),
  composite: new CompositeStrategy(),
}

// 默认兜底策略
class DefaultStrategy implements QuestionStrategy {
  getDefaultAnswer() {
    return null
  }
  isEmpty() {
    return true
  }
  checkCorrect() {
    return false
  }
  formatForSubmit(val: any, questionIndex: number, buildSubAnswer?: any, question?: any) {
    return null
  }
  buildOriginalAnswer() {
    return {}
  }
}

const defaultStrategy = new DefaultStrategy()

/**
 * 根据题目类型获取题型策略实例
 * @param type 题目类型
 */
export const getQuestionStrategy = (type?: string): QuestionStrategy => {
  if (!type) return defaultStrategy
  return strategies[type] || defaultStrategy
}
